import { View, Text, FlatList, ActivityIndicator, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }, { id: "p3", name: "Ном" },
];
const fakeApi = () => new Promise((res) => setTimeout(() => res(PRODUCTS), 200));

function App() {
  const [items, setItems] = useState(null); // null = ачаалж байна
  useEffect(() => {
    let alive = true;
    fakeApi().then((data) => { if (alive) setItems(data); });
    return () => { alive = false; };
  }, []);

  if (items === null) {
    return <View style={styles.center}><ActivityIndicator nativeID="spin" size="large" /></View>;
  }
  if (items.length === 0) {
    return <View style={styles.center}><Text nativeID="empty" style={styles.empty}>Бараа алга</Text></View>;
  }
  return (
    <FlatList
      nativeID="list"
      data={items}
      keyExtractor={(x) => x.id}
      renderItem={({ item }) => <Text testID="row" style={styles.row}>{item.name}</Text>}
      style={styles.list}
    />
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, alignItems: "center", justifyContent: "center" },
  list: { flex: 1, padding: 16 },
  row: { fontSize: 16, paddingVertical: 12, borderBottomWidth: 1, borderColor: "#e2e8f0" },
  empty: { fontSize: 16, color: "#64748b" },
});

registerRootComponent(App);
